<script module lang="ts">
/**
 * Disclosure list (`design/components/accordion.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/accordion.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import * as zag from '@zag-js/accordion'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Render,
  agentMember,
  attributes,
  joinSlot,
  normalizeProps,
  refList,
  useDirection,
  watchEffect,
} from '@polymorph/svelte'
import { useKeyedPresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/structure/accordion.module.css'

export type AccordionHeadingLevel = NonNullable<AccordionProps['headingLevel']>

export interface AccordionItem {
  value: string
  label: string
  content: Snippet | string
  disabled?: boolean
}

export interface AccordionProps {
  /**
   * The open item may be closed again, leaving the list shut.
   */
  collapsible?: boolean
  defaultValue?: string | string[]
  headingLevel?: 3 | 4
  items: AccordionItem[]
  /**
   * Keeps a closed item's content in the document and `hidden`, so a page's server markup
   * carries it and its state survives a close. Without it the React member leaves closed content
   * out. The generated members keep it in every case.
   */
  keepMounted?: boolean
  onValueChange?: ((value: string) => void) | ((value: string[]) => void)
  type?: 'single' | 'multiple'
  value?: string | string[]
}
</script>

<script lang="ts">
let {
  collapsible,
  defaultValue,
  headingLevel = 3,
  items,
  onValueChange,
  type = 'single',
  value,
}: AccordionProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({}))
let heights = $state(new Map())
const regions = refList()
let root = $state<HTMLElement | null>(null)
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      multiple: type === 'multiple',
      collapsible: type === 'multiple' || (collapsible ?? true),
      value:
        value === undefined
          ? undefined
          : Array.isArray(value)
            ? value
            : value === ''
              ? []
              : [value],
      defaultValue:
        defaultValue === undefined
          ? undefined
          : Array.isArray(defaultValue)
            ? defaultValue
            : [defaultValue],
      onValueChange: (details) => {
        ;(onValueChange as ((...args: any[]) => unknown) | undefined)?.(
          type === 'multiple' ? details.value : (details.value[0] ?? ''),
        )
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const regionPresent = useKeyedPresence(
  () => api.value,
  () => regions.current,
  (element) =>
    items.find((item) => api.getItemContentProps({ value: item.value }).id === element.id)?.value,
)
const effect1 = () => {
  heights = new Map(
    (regions.current ?? []).map((region) => [region.id, region.scrollHeight + 'px']),
  )
}
watchEffect(effect1, { watch: () => api.value })
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Accordion',
    element: () => root,
    state: () => ({
      value: api.value,
      items: items.map((item) => ({
        id: item.value,
        label: item.label,
        ...(item.disabled === true ? { disabled: true } : {}),
      })),
    }),
    actions: {
      expand: {
        argument: 'id',
        run: (value) =>
          api.value.includes(value) ||
          api.setValue(type === 'multiple' ? [...api.value, value] : [value]),
      },
      collapse: {
        argument: 'id',
        run: (value) =>
          (() => {
            if (!api.value.includes(value)) return
            if (type !== 'multiple' && !(collapsible ?? true)) {
              throw new Error('This accordion keeps one item open; expand another item instead.')
            }
            api.setValue(api.value.filter((shown) => shown !== value))
          })(),
      },
    },
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    {...attributes(api.getRootProps())}
    class={styles.root}
    data-member="accordion"
    >{#each items as item (item.value)
      }<div
        {...attributes(api.getItemProps({ value: item.value, disabled: item.disabled }))}
        class={styles.item}
        ><svelte:element this={headingLevel === 4 ? 'h4' : 'h3'} class={styles.header}
          ><button
            {...attributes(api.getItemTriggerProps({ value: item.value, disabled: item.disabled }))}
            class={styles.trigger}
            data-accordion-part="trigger"
            ><span class={styles.label}>{item.label}</span
            ><span class={styles.chevron}><Icon name="down" /></span
          ></button
        ></svelte:element
        ><div
          {@attach regions.attach}
          {...attributes(api.getItemContentProps({ value: item.value, disabled: item.disabled }))}
          class={styles.content}
          style:--radix-accordion-content-height={heights.get(api.getItemContentProps({ value: item.value, disabled: item.disabled }).id)}
          hidden={!regionPresent.current.has(item.value)}
          data-accordion-part="region"
          ><div class={styles.inner}
            >{#if typeof item.content === 'string'
              }{item.content
            }{:else
              }<Render node={item.content}
            />{/if
          }</div
        ></div
      ></div
    >{/each
  }</div
>{/if
}{@render joined.end?.()}
